/*
 * WebGL mesh deformation for the chibi character on the 故障终端 shelf stage.
 * Only loaded on capable devices (deviceMemory >= 4, not TauriTavern, prefers-reduced-motion off).
 */

const RIG = {"atlas":"../skins/gt-atlas.webp","atlasSize":[1024,298],"meshes":{"am":{"x0":208,"y0":0,"nx":55,"ny":80,"step":16,"cells":"","w":"","uv":[222,5,0.23837902264600716,0.23890234059725585,1,1],"tile":[0.00146484375,0.0050335570469798654,0.19580078125,0.9949664429530202]},"bb":{"x0":304,"y0":368,"nx":42,"ny":57,"step":16,"cells":"","w":"","uv":[313,379,0.23501577287066247,0.23542857142857143,203,1],"tile":[0.19873046875,0.0050335570469798654,0.34326171875,0.6929530201342282]},"bh":{"x0":160,"y0":0,"nx":60,"ny":38,"step":16,"cells":"","w":"","uv":[168,0,0.23593073593073594,0.23467600700525393,354,1],"tile":[0.34619140625,0.0050335570469798654,0.55810546875,0.4513422818791946]},"bo":{"x0":592,"y0":368,"nx":8,"ny":7,"step":16,"cells":"vv////cB","w":"","uv":[600,382,0.22988505747126436,0.23880597014925373,746,1],"tile":[0.72900390625,0.0050335570469798654,0.74755859375,0.05536912751677853]},"be":{"x0":448,"y0":240,"nx":25,"ny":14,"step":16,"cells":"wP8B8P8P/P8f/v8///9///////////////9//v9//P8f+P8PwP8B","w":"","uv":[461,255,0.2349570200573066,0.23756906077348067,662,1],"tile":[0.64697265625,0.0050335570469798654,0.72607421875,0.14597315436241612]},"bf":{"x0":512,"y0":432,"nx":26,"ny":17,"step":16,"cells":"gP8A4P8H4P8f4P9/8P//4f//x///n///P/////7///3///v///f//+///////////38=","w":"","uv":[525,450,0.23497267759562843,0.2361111111111111,574,1],"tile":[0.56103515625,0.0050335570469798654,0.64404296875,0.17281879194630873]}},"A":{"box":[222,4],"f":0.14907332796132153,"pl":[405,90],"pr":[850,70],"neck":[640,470]},"B":{"box":[167,0],"f":0.147175815433572,"pl":[420,95],"pr":[880,80],"neck":[680,455]}};

const PAD = 14, CH_H = 185;
const AY = [.6, .5, .3, 0, -.3, -.9, -1.2, -1.6, -2.0, -2.2, -2.4, -2.6, -2.7, -2.8, -2.7, -2.4, -1.9, -1.1, -.3, .1, .4, .6];
const A_MS = 44 / 58.8 * 1000, A_T0 = 1667 - 2 * A_MS;

function aCurve(t) {
    const n = AY.length, u = ((t - A_T0) / A_MS % 1 + 1) % 1 * n, i = Math.floor(u), f = u - i;
    const p0 = AY[(i - 1 + n) % n], p1 = AY[i % n], p2 = AY[(i + 1) % n], p3 = AY[(i + 2) % n];
    return .5 * (2 * p1 + (-p0 + p2) * f + (2 * p0 - 5 * p1 + 4 * p2 - p3) * f * f + (-p0 + 3 * p1 - 3 * p2 + p3) * f * f * f);
}

const B_MS = 540, B_T0 = 1446 - 540 / 4;
const bBob = t => Math.sin((t - B_T0) / B_MS * 2 * Math.PI);
const headY = (key, t) => key === 'A' ? aCurve(t) : 3.4 * bBob(t);

const SPR = { A: { k: 101, c: 6, g: -80 }, B: { k: 101, c: 6, g: -73 } };
class Sim {
    constructor(key) { this.key = key; this.reset(); }
    reset() { this.t = 0; this.x = 0; this.v = 0; }
    to(t) {
        if (t < this.t || t - this.t > 4000) this.reset();
        const s = SPR[this.key], h = 1000 / 240, key = this.key;
        while (this.t + h <= t) {
            const a = (headY(key, this.t + h) - 2 * headY(key, this.t) + headY(key, this.t - h)) / (h * h / 1e6);
            this.v += (-s.k * this.x - s.c * this.v + s.g * a / 60) * h / 1000;
            this.x += this.v * h / 1000;
            this.t += h;
        }
        return this.x;
    }
}

const VS = [
    'attribute vec2 a_p; attribute vec4 a_w;',
    'uniform vec2 u_pl; uniform vec2 u_pr; uniform vec2 u_neck; uniform vec3 u_rot; uniform vec2 u_ht; uniform vec2 u_bt;',
    'uniform vec4 u_uv; uniform vec2 u_at; uniform vec2 u_as; uniform vec4 u_m; uniform vec2 u_cs;',
    'varying vec2 v_uv;',
    'vec2 rot(vec2 p, vec2 c, float a) { float s = sin(a), k = cos(a); p -= c; return c + vec2(p.x * k - p.y * s, p.x * s + p.y * k); }',
    'void main() {',
    '  v_uv = ((a_p - u_uv.xy) * u_uv.zw + u_at) / u_as;',
    '  float wl = a_w.z * (0.78 + 0.36 * a_w.z);',
    '  float wr = a_w.w * (0.78 + 0.36 * a_w.w);',
    '  vec2 p = rot(a_p, u_pl, u_rot.x * wl);',
    '  p = rot(p, u_pr, u_rot.y * wr);',
    '  p = rot(p, u_neck, u_rot.z * a_w.y) + u_ht * a_w.y;',
    '  p += u_bt * a_w.x;',
    '  vec2 c = (p - u_m.xy) * u_m.z + u_m.w;',
    '  gl_Position = vec4(c.x / u_cs.x * 2.0 - 1.0, 1.0 - c.y / u_cs.y * 2.0, 0.0, 1.0);',
    '}'
].join('\n');

const FS = 'precision mediump float; varying vec2 v_uv; uniform sampler2D u_tex; uniform float u_alpha; uniform vec4 u_tile;' +
    'void main() { if (v_uv.x < u_tile.x || v_uv.y < u_tile.y || v_uv.x > u_tile.z || v_uv.y > u_tile.w) discard; gl_FragColor = texture2D(u_tex, v_uv) * u_alpha; }';

function b64(s) {
    const b = atob(s), a = new Uint8Array(b.length);
    for (let i = 0; i < b.length; i++) a[i] = b.charCodeAt(i);
    return a;
}

export function attachCharGl(gp) {
    if (!gp) return () => {};
    const poses = [
        { key: 'A', el: gp.querySelector('.pa'), meshes: ['am'] },
        { key: 'B', el: gp.querySelector('.pb'), meshes: ['bb', 'bh', 'bo', 'be', 'bf'] },
    ];
    let alive = true, running = false, raf = 0;

    function makePose(P) {
        if (!P.el) return null;
        const R = RIG[P.key], f = R.f;
        const stat = P.el.querySelector('img.stat'), boxW = parseFloat(stat?.style?.width) || 125;
        const cv = document.createElement('canvas');
        cv.className = 'gl';
        cv.style.cssText = `position:absolute;left:${-PAD}px;top:${-PAD}px;width:${boxW + 2 * PAD}px;height:${CH_H + 2 * PAD}px;pointer-events:none`;
        const gl = cv.getContext('webgl', { premultipliedAlpha: true, alpha: true, antialias: true });
        if (!gl) return null;
        P.el.appendChild(cv);
        const sh = (type, src) => { const s = gl.createShader(type); gl.shaderSource(s, src); gl.compileShader(s); return s; };
        const prog = gl.createProgram();
        gl.attachShader(prog, sh(gl.VERTEX_SHADER, VS));
        gl.attachShader(prog, sh(gl.FRAGMENT_SHADER, FS));
        gl.linkProgram(prog);
        gl.useProgram(prog);
        const U = {};
        ['u_pl', 'u_pr', 'u_neck', 'u_rot', 'u_ht', 'u_bt', 'u_uv', 'u_at', 'u_as', 'u_m', 'u_cs', 'u_tex', 'u_alpha', 'u_tile']
            .forEach(n => { U[n] = gl.getUniformLocation(prog, n); });
        const aP = gl.getAttribLocation(prog, 'a_p'), aW = gl.getAttribLocation(prog, 'a_w');
        const M = {};
        P.meshes.forEach(k => {
            const m = RIG.meshes[k], cells = b64(m.cells), w = b64(m.w), nv = m.nx * m.ny;
            const pos = new Float32Array(nv * 2), wt = new Float32Array(nv * 4), idx = [];
            for (let j = 0; j < m.ny; j++) for (let i = 0; i < m.nx; i++) {
                const v = j * m.nx + i;
                pos[v * 2] = m.x0 + i * m.step; pos[v * 2 + 1] = m.y0 + j * m.step;
                for (let c = 0; c < 4; c++) wt[v * 4 + c] = w[v * 4 + c] / 255;
            }
            for (let j = 0; j < m.ny - 1; j++) for (let i = 0; i < m.nx - 1; i++) {
                const q = j * (m.nx - 1) + i;
                if (!(cells[q >> 3] & (1 << (q & 7)))) continue;
                const a = j * m.nx + i, b = a + 1, d = a + m.nx, e = d + 1;
                idx.push(a, b, d, b, e, d);
            }
            const o = { n: idx.length, uv: m.uv, tile: m.tile };
            o.pb = gl.createBuffer(); gl.bindBuffer(gl.ARRAY_BUFFER, o.pb); gl.bufferData(gl.ARRAY_BUFFER, pos, gl.STATIC_DRAW);
            o.wb = gl.createBuffer(); gl.bindBuffer(gl.ARRAY_BUFFER, o.wb); gl.bufferData(gl.ARRAY_BUFFER, wt, gl.STATIC_DRAW);
            o.ib = gl.createBuffer(); gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER, o.ib); gl.bufferData(gl.ELEMENT_ARRAY_BUFFER, new Uint16Array(idx), gl.STATIC_DRAW);
            M[k] = o;
        });
        const tex = gl.createTexture();
        let ready = false;
        const img = new Image();
        img.onload = () => {
            if (!alive) return;
            gl.bindTexture(gl.TEXTURE_2D, tex);
            gl.pixelStorei(gl.UNPACK_PREMULTIPLY_ALPHA_WEBGL, true);
            gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, gl.RGBA, gl.UNSIGNED_BYTE, img);
            gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
            gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
            gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
            gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
            ready = true;
            P.el.querySelectorAll('img.stat').forEach(e => { e.style.visibility = 'hidden'; });
            kick();
        };
        img.src = RIG.atlas;
        gl.enable(gl.BLEND); gl.blendFunc(gl.ONE, gl.ONE_MINUS_SRC_ALPHA);
        gl.uniform1i(U.u_tex, 0);
        gl.uniform2f(U.u_as, RIG.atlasSize[0], RIG.atlasSize[1]);
        gl.uniform2f(U.u_pl, R.pl[0], R.pl[1]); gl.uniform2f(U.u_pr, R.pr[0], R.pr[1]); gl.uniform2f(U.u_neck, R.neck[0], R.neck[1]);
        const sim = new Sim(P.key), D2R = Math.PI / 180, cssW = boxW + 2 * PAD, cssH = CH_H + 2 * PAD;

        function draw(k, alpha) {
            const m = M[k];
            gl.uniform4f(U.u_uv, m.uv[0], m.uv[1], m.uv[2], m.uv[3]); gl.uniform2f(U.u_at, m.uv[4], m.uv[5]);
            gl.uniform1f(U.u_alpha, alpha);
            gl.uniform4f(U.u_tile, m.tile[0], m.tile[1], m.tile[2], m.tile[3]);
            gl.bindBuffer(gl.ARRAY_BUFFER, m.pb); gl.enableVertexAttribArray(aP); gl.vertexAttribPointer(aP, 2, gl.FLOAT, false, 0, 0);
            gl.bindBuffer(gl.ARRAY_BUFFER, m.wb); gl.enableVertexAttribArray(aW); gl.vertexAttribPointer(aW, 4, gl.FLOAT, false, 0, 0);
            gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER, m.ib);
            gl.drawElements(gl.TRIANGLES, m.n, gl.UNSIGNED_SHORT, 0);
        }
        return {
            key: P.key,
            cv,
            cleanup() {
                cv.remove();
                P.el.querySelectorAll('img.stat').forEach(e => { e.style.visibility = ''; });
            },
            render(t, still) {
                if (!ready) return;
                const s = parseFloat(getComputedStyle(gp).getPropertyValue('--s')) || 1, dpr = Math.min(window.devicePixelRatio || 1, 3);
                const sc = s * dpr, w = Math.round(cssW * sc), h = Math.round(cssH * sc);
                if (cv.width !== w || cv.height !== h) { cv.width = w; cv.height = h; }
                gl.viewport(0, 0, w, h);
                gl.uniform2f(U.u_cs, w, h);
                gl.uniform4f(U.u_m, R.box[0], R.box[1], f * sc, PAD * sc);
                const th = still ? 0 : sim.to(t), hy = still ? 0 : headY(P.key, t), k = 1 / f;
                gl.uniform3f(U.u_rot, -th * D2R, th * D2R, 0);
                if (P.key === 'A') {
                    const body = still ? 0 : .8 * aCurve(t - 35), lag = still ? 0 : aCurve(t - 70);
                    gl.uniform3f(U.u_rot, -th * D2R, th * D2R, (hy - lag) * .25 * D2R);
                    gl.uniform2f(U.u_bt, 0, body * k); gl.uniform2f(U.u_ht, 0, ((hy - body) + (hy - lag) * .22) * k);
                } else {
                    const v = still ? 0 : bBob(t);
                    gl.uniform3f(U.u_rot, -th * D2R, th * D2R, 0);
                    gl.uniform2f(U.u_bt, -.5 * v * k, 1.6 * v * k); gl.uniform2f(U.u_ht, -.4 * v * k, 1.8 * v * k);
                }
                gl.clearColor(0, 0, 0, 0); gl.clear(gl.COLOR_BUFFER_BIT);
                if (P.key === 'A') draw('am', 1);
                else {
                    let eye = 0;
                    if (!still) {
                        if (t < 255) eye = 1;
                        else if (t < 315) eye = 1 - (t - 255) / 60;
                        else if (t > 1500 && t < 1500 + 8 * 2600) {
                            const bp = ((t - 1500) % 2600) / 2600;
                            if (bp > .935 && bp < .995) eye = Math.sin((bp - .935) / .06 * Math.PI);
                        }
                    }
                    const mouth = (!still && t < 1430) ? (t < 1370 ? 1 : 1 - (t - 1370) / 60) : 0;
                    draw('bb', 1); draw('bh', 1); if (mouth > 0) draw('bo', mouth); if (eye > 0) draw('be', eye); draw('bf', 1);
                }
            },
        };
    }

    const R2 = poses.map(makePose).filter(Boolean);
    if (!R2.length) return () => {};

    function clockOf(cv) {
        const an = cv.getAnimations ? cv.getAnimations() : [];
        for (let i = 0; i < an.length; i++) if (an[i].animationName === 'clk') return an[i].currentTime;
        return null;
    }
    function shown(r) {
        const k = gp.dataset.kind, st = gp.dataset.state;
        if (r.key === 'A') return k !== 'turn' || st === 'standup' || st === 'closing';
        return k === 'turn';
    }
    function isIdle() { return !alive || gp.hidden || gp.classList.contains('paused'); }
    function frame() {
        if (isIdle()) { running = false; return; }
        R2.forEach(r => { if (!shown(r)) return; const t = clockOf(r.cv); r.render(t == null ? 0 : t, t == null); });
        raf = requestAnimationFrame(frame);
    }
    function kick() { if (!running && !isIdle()) { running = true; raf = requestAnimationFrame(frame); } }
    const mo = new MutationObserver(kick);
    mo.observe(gp, { attributes: true, attributeFilter: ['hidden', 'data-state', 'data-kind', 'class'] });
    kick();

    return () => {
        alive = false;
        mo.disconnect();
        cancelAnimationFrame(raf);
        R2.forEach(r => r.cleanup());
    };
}
